import { logger, Event as LogEvent } from '../utils/logger';

/**
 * Per-install device identity for the plain browser. The key pair is generated by WebCrypto with
 * `extractable: false`, so page JavaScript (an XSS payload included) can never read the private
 * key — it can only ask the browser to use it. The key is persisted in IndexedDB as a CryptoKey
 * object, never as raw bytes. It is NOT hardware-backed, hence `level: 'browser'`.
 *
 * The key identifies the device, not the user, so it deliberately survives logout.
 * Electron and the mobile WebView will use native hardware-backed keys instead.
 *
 * Only key creation lives here.
 * see the integration point in hooks/useDeviceIdentity.ts.
 */

const DB_NAME = 'xyne-device-identity';
const DB_VERSION = 1;
const IDENTITY_STORE = 'identity';
const IDENTITY_KEY = 'current';
const LOCK_NAME = 'xyne-device-identity';

const KEY_ALGORITHM: EcKeyGenParams = { name: 'ECDSA', namedCurve: 'P-256' };

export type DeviceIdentityLevel = 'browser';
export type DeviceIdentityPlatform = 'web';

export interface DeviceIdentity {
  /** base64url SHA-256 of the SPKI public key — stable for the life of the key. */
  deviceId: string;
  /** SPKI DER public key, base64. */
  publicKey: string;
  algorithm: 'P-256';
  level: DeviceIdentityLevel;
  platform: DeviceIdentityPlatform;
}

interface StoredIdentity {
  keyPair: CryptoKeyPair;
  deviceId: string;
  publicKey: string;
  createdAt: number;
}

let dbPromise: Promise<IDBDatabase> | null = null;

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function logDeviceIdentityWarning(message: string, error?: unknown): void {
  logger.warn(LogEvent.FRONTEND_ERROR, {
    type: 'device_identity',
    message: '[DeviceIdentity] ' + message,
    ...(error !== undefined ? { error: getErrorMessage(error) } : {}),
  });
}

function isSupported(): boolean {
  return (
    typeof window !== 'undefined' &&
    window.isSecureContext &&
    typeof crypto !== 'undefined' &&
    !!crypto.subtle &&
    typeof indexedDB !== 'undefined'
  );
}

function openDB(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise<IDBDatabase>((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onerror = (): void => reject(new Error('Failed to open device identity IndexedDB'));
    request.onsuccess = (): void => resolve(request.result);
    request.onupgradeneeded = (event): void => {
      const db = (event.target as IDBOpenDBRequest).result;
      if (!db.objectStoreNames.contains(IDENTITY_STORE)) {
        db.createObjectStore(IDENTITY_STORE);
      }
    };
  }).catch((err: unknown) => {
    // Let the next call retry instead of caching the failure forever.
    dbPromise = null;
    throw err;
  });
  return dbPromise;
}

async function idbGet<T>(storeName: string, key: string): Promise<T | undefined> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const request = db.transaction([storeName], 'readonly').objectStore(storeName).get(key);
    request.onsuccess = (): void => resolve(request.result as T | undefined);
    request.onerror = (): void => reject(new Error(`Failed to read ${storeName} from IndexedDB`));
  });
}

async function idbPut(storeName: string, key: string, value: unknown): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const request = db.transaction([storeName], 'readwrite').objectStore(storeName).put(value, key);
    request.onsuccess = (): void => resolve();
    request.onerror = (): void => reject(new Error(`Failed to write ${storeName} to IndexedDB`));
  });
}

async function withLock<R>(fn: () => Promise<R>): Promise<R> {
  if (typeof navigator !== 'undefined' && navigator.locks) {
    return navigator.locks.request(LOCK_NAME, fn);
  }
  return fn();
}

function toBase64(bytes: Uint8Array): string {
  let binary = '';
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary);
}

function toBase64Url(bytes: Uint8Array): string {
  return toBase64(bytes).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

async function createIdentity(): Promise<StoredIdentity> {
  // Only the private key honours `extractable: false`; the public key is always exportable.
  const keyPair = await crypto.subtle.generateKey(KEY_ALGORITHM, false, ['sign', 'verify']);
  const spki = new Uint8Array(await crypto.subtle.exportKey('spki', keyPair.publicKey));
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', spki));
  return {
    keyPair,
    deviceId: toBase64Url(digest),
    publicKey: toBase64(spki),
    createdAt: Date.now(),
  };
}

function toPublicIdentity(stored: StoredIdentity): DeviceIdentity {
  return {
    deviceId: stored.deviceId,
    publicKey: stored.publicKey,
    algorithm: 'P-256',
    level: 'browser',
    platform: 'web',
  };
}

/**
 * Returns this browser's device identity, creating and persisting the key pair on first use.
 * Returns null when WebCrypto/IndexedDB are unavailable (insecure origin, some private modes) —
 * callers should carry on without a device identity.
 */
export async function getOrCreateDeviceIdentity(): Promise<DeviceIdentity | null> {
  if (!isSupported()) {
    logDeviceIdentityWarning('WebCrypto or IndexedDB unavailable — skipping device identity');
    return null;
  }
  try {
    // The lock stops two tabs opened at once from each generating (and overwriting) a key.
    return await withLock(async () => {
      const existing = await idbGet<StoredIdentity>(IDENTITY_STORE, IDENTITY_KEY);
      if (existing?.keyPair?.privateKey) return toPublicIdentity(existing);

      const created = await createIdentity();
      await idbPut(IDENTITY_STORE, IDENTITY_KEY, created);
      return toPublicIdentity(created);
    });
  } catch (err: unknown) {
    logDeviceIdentityWarning('Failed to get or create device identity', err);
    return null;
  }
}
